const part = ($input.first().json.content || []).find((c) => c.type === 'text');
const sent = part ? part.text : null;
if (!sent || sent.delivered !== true) {
  throw new Error('send_telegram_message did not confirm delivery: ' + JSON.stringify(sent).slice(0, 300));
}

// Advance the watermark only after a confirmed delivery — exactly the agent's
// rule ("only after a successful full news-digest delivery"). A failed send
// leaves the window open, so the next run re-reads the same posts.
const store = $getWorkflowStaticData('global');
store.newsDigestLastReadAt = $('Resolve digest window').first().json.nowISO;

return [
  {
    json: {
      delivered: true,
      chatId: sent.chatId,
      messageId: sent.messageId,
      watermark: store.newsDigestLastReadAt,
      chunks: $('Combine the shortlists').first().json.chunkCount,
    },
  },
];
